import SwiftUI
import SwiftData

@Model
class Project {
    var name: String
    @Relationship(deleteRule: .cascade) var tasks: [TaskItem] = []
    init(name: String) { self.name = name }
}

@Model
class TaskItem {
    var title: String
    var isDone: Bool = false
    init(title: String) { self.title = title }
}

struct ProjectListView: View {
    @Environment(\.modelContext) private var context
    @Query private var projects: [Project]
    @State private var newProject = ""

    var body: some View {
        NavigationStack {
            VStack(spacing: 16) {
                TextField("Projektname", text: $newProject)
                    .textFieldStyle(.roundedBorder)

                Button("Projekt hinzufügen") {
                    let project = Project(name: newProject)
                    context.insert(project)
                    try? context.save()
                    newProject = ""
                }
                .buttonStyle(.borderedProminent)

                List(projects) { project in
                    NavigationLink(destination: TaskListView(project: project)) {
                        Text(project.name)
                    }
                }
            }
            .padding()
            .navigationTitle("Projekte")
        }
    }
}

struct TaskListView: View {
    @Environment(\.modelContext) private var context
    @Bindable var project: Project
    @State private var newTask = ""

    var body: some View {
        VStack(spacing: 16) {
            TextField("Neue Aufgabe", text: $newTask)
                .textFieldStyle(.roundedBorder)

            Button("Hinzufügen") {
                let task = TaskItem(title: newTask)
                project.tasks.append(task)
                try? context.save()
                newTask = ""
            }
            .buttonStyle(.borderedProminent)

            List(project.tasks) { task in
                HStack {
                    Text(task.title)
                    Spacer()
                    Image(systemName: task.isDone ? "checkmark.circle.fill" : "circle")
                        .onTapGesture {
                            task.isDone.toggle()
                            try? context.save()
                        }
                }
            }
        }
        .padding()
        .navigationTitle(project.name)
    }
}

