import SwiftUI
import SwiftData

@Model
class Expense {
    var title: String
    var amount: Double
    var date: Date
    init(title: String, amount: Double, date: Date = .now) {
        self.title = title
        self.amount = amount
        self.date = date
    }
}

struct FilteredListView: View {
    @Environment(\.modelContext) private var context
    @Query(sort: [SortDescriptor(\.amount, order: .reverse)], predicate: #Predicate { $0.amount > 50 }) private var expenses: [Expense]
    @State private var title = ""
    @State private var amount = ""

    var body: some View {
        VStack(spacing: 16) {
            TextField("Titel", text: $title)
                .textFieldStyle(.roundedBorder)
            TextField("Betrag", text: $amount)
                .keyboardType(.decimalPad)
                .textFieldStyle(.roundedBorder)

            Button("Speichern") {
                if let value = Double(amount) {
                    let expense = Expense(title: title, amount: value)
                    context.insert(expense)
                    try? context.save()
                    title = ""
                    amount = ""
                }
            }
            .buttonStyle(.borderedProminent)

            List(expenses) { expense in
                HStack {
                    VStack(alignment: .leading) {
                        Text(expense.title)
                            .font(.headline)
                        Text(expense.date, style: .date)
                            .font(.caption)
                            .foregroundColor(.gray)
                    }
                    Spacer()
                    Text(String(format: "%.2f €", expense.amount))
                        .bold()
                }
            }
        }
        .padding()
        .navigationTitle("Ausgaben > 50€")
    }
}

