import SwiftUI
import SwiftData

@Model
class PhotoItem {
    var filePath: String
    init(filePath: String) { self.filePath = filePath }
}

struct PhotoView: View {
    @Environment(\.modelContext) private var context
    @Query private var items: [PhotoItem]
    @State private var image: UIImage? = nil

    func saveImage(_ img: UIImage) {
        let url = FileManager.default.temporaryDirectory.appending(path: "photo_\(UUID().uuidString).png")
        if let data = img.pngData() {
            try? data.write(to: url)
            context.insert(PhotoItem(filePath: url.path()))
            try? context.save()
        }
    }

    var body: some View {
        VStack {
            Button("Bild speichern (Dummy)") {
                saveImage(UIImage(systemName: "photo")!)
            }
            .buttonStyle(.borderedProminent)

            List(items) { item in
                if let img = UIImage(contentsOfFile: item.filePath) {
                    Image(uiImage: img).resizable().frame(width: 80, height: 80)
                }
            }
        }
        .padding()
    }
}

